-- Generated from the existing preset registry. Additive catalog promotion only.
-- Existing Core/Urban Kicks selections, drafts and releases are never rewritten.
BEGIN;
ALTER TABLE public.themes ADD COLUMN catalog_visible boolean NOT NULL DEFAULT true;
UPDATE public.themes SET catalog_visible=false WHERE slug IN ('letbuyy-core','urban-kicks') AND owned_by_site_id IS NULL AND NOT is_site_private;
DO $catalog$
DECLARE base public.themes; item jsonb; doc jsonb; bundle jsonb;
BEGIN
 SELECT * INTO STRICT base FROM public.themes WHERE slug='letbuyy-core' AND NOT is_site_private AND owned_by_site_id IS NULL;
 IF base.default_template#>>'{liquidBundle,package,slug}' IS DISTINCT FROM 'letbuyy-core-liquid' THEN
  RAISE EXCEPTION 'Canonical Core bundle unavailable'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements($listings$[{"id":"7b669c70-0000-4000-8000-000000000001","slug":"letbuyy-forge","name":"Forge","presetId":"forge","description":"A precise, technical look for electronics, gadgets, and tech accessories. Deep navy authority with electric-cyan accents — built for spec-heavy products.","category":"electronics","thumbnail":"/theme-previews/forge.svg","settings":{"primaryColor":"#1E3A5F","secondaryColor":"#1E40AF","accentColor":"#00B4D8","backgroundColor":"#FFFFFF","textColor":"#1A202C","surfaceColor":"#F0F4F8","fontFamily":"Inter","bodyFontFamily":"Inter","headingFontFamily":"Inter","borderRadius":8},"preview":{"label":"Forge","summary":"A precise, technical look for electronics, gadgets, and tech accessories. Deep navy authority with electric-cyan accents — built for spec-heavy products.","swatches":["#1E3A5F","#00B4D8","#F0F4F8"],"headingFont":"Inter","sectionCount":7}},{"id":"7b669c70-0000-4000-8000-000000000002","slug":"letbuyy-sense","name":"Sense","presetId":"sense","description":"Editorial fashion with bold typography and lookbook imagery. Near-black and crimson for a modern, aspirational apparel brand.","category":"fashion","thumbnail":"/theme-previews/sense.svg","settings":{"primaryColor":"#1A1A2E","secondaryColor":"#2D2D44","accentColor":"#E63946","backgroundColor":"#FFFFFF","textColor":"#1A1A2E","surfaceColor":"#FAFAFA","fontFamily":"Inter","bodyFontFamily":"Inter","headingFontFamily":"Playfair Display","borderRadius":4},"preview":{"label":"Sense","summary":"Editorial fashion with bold typography and lookbook imagery. Near-black and crimson for a modern, aspirational apparel brand.","swatches":["#1A1A2E","#E63946","#FAFAFA"],"headingFont":"Playfair Display","sectionCount":6}},{"id":"7b669c70-0000-4000-8000-000000000003","slug":"letbuyy-aura","name":"Aura","presetId":"aura","description":"Soft and luxurious for beauty, skincare, and cosmetics. Muted rose with a champagne accent — the aesthetic of a premium beauty brand.","category":"beauty","thumbnail":"/theme-previews/aura.svg","settings":{"primaryColor":"#C2798B","secondaryColor":"#9E5A6F","accentColor":"#D4AF7A","backgroundColor":"#FFFFFF","textColor":"#2D1B22","surfaceColor":"#FFF8F9","fontFamily":"Lato","bodyFontFamily":"Lato","headingFontFamily":"Cormorant Garamond","borderRadius":16},"preview":{"label":"Aura","summary":"Soft and luxurious for beauty, skincare, and cosmetics. Muted rose with a champagne accent — the aesthetic of a premium beauty brand.","swatches":["#C2798B","#D4AF7A","#FFF8F9"],"headingFont":"Cormorant Garamond","sectionCount":7}},{"id":"7b669c70-0000-4000-8000-000000000004","slug":"letbuyy-craft","name":"Craft","presetId":"craft","description":"Warm, artisanal aesthetics for furniture, home decor, and handcrafted goods. Rich walnut earth tones that convey quality and longevity.","category":"furniture","thumbnail":"/theme-previews/craft.svg","settings":{"primaryColor":"#3E2723","secondaryColor":"#5D3B2E","accentColor":"#8D6E63","backgroundColor":"#FFFFFF","textColor":"#2C1B12","surfaceColor":"#FFF8F0","fontFamily":"Source Sans Pro","bodyFontFamily":"Source Sans Pro","headingFontFamily":"Libre Baskerville","borderRadius":6},"preview":{"label":"Craft","summary":"Warm, artisanal aesthetics for furniture, home decor, and handcrafted goods. Rich walnut earth tones that convey quality and longevity.","swatches":["#3E2723","#8D6E63","#FFF8F0"],"headingFont":"Libre Baskerville","sectionCount":9}},{"id":"7b669c70-0000-4000-8000-000000000005","slug":"letbuyy-refresh","name":"Refresh","presetId":"refresh","description":"Fresh and inviting for grocery, organic food, and daily essentials. Deep forest green with warm orange — the look of a trusted neighbourhood store.","category":"food","thumbnail":"/theme-previews/refresh.svg","settings":{"primaryColor":"#2D6A4F","secondaryColor":"#1B4332","accentColor":"#F4A261","backgroundColor":"#FFFFFF","textColor":"#1B2521","surfaceColor":"#F8FFF4","fontFamily":"Inter","bodyFontFamily":"Inter","headingFontFamily":"Inter","borderRadius":10},"preview":{"label":"Refresh","summary":"Fresh and inviting for grocery, organic food, and daily essentials. Deep forest green with warm orange — the look of a trusted neighbourhood store.","swatches":["#2D6A4F","#F4A261","#F8FFF4"],"headingFont":"Inter","sectionCount":7}},{"id":"7b669c70-0000-4000-8000-000000000006","slug":"letbuyy-ride","name":"Ride","presetId":"ride","description":"High-energy design for sports equipment, fitness gear, and outdoor brands. Performance orange and carbon black — built for movement.","category":"sports","thumbnail":"/theme-previews/ride.svg","settings":{"primaryColor":"#FF4D00","secondaryColor":"#1C1C1C","accentColor":"#FFD100","backgroundColor":"#FFFFFF","textColor":"#111111","surfaceColor":"#F5F5F5","fontFamily":"Inter","bodyFontFamily":"Inter","headingFontFamily":"Inter","borderRadius":6},"preview":{"label":"Ride","summary":"High-energy design for sports equipment, fitness gear, and outdoor brands. Performance orange and carbon black — built for movement.","swatches":["#FF4D00","#FFD100","#F5F5F5"],"headingFont":"Inter","sectionCount":7}},{"id":"7b669c70-0000-4000-8000-000000000007","slug":"letbuyy-dawn","name":"Dawn","presetId":"dawn","description":"Calm and scholarly for bookshops, stationery, and educational content. Warm parchment tones with a slate-blue accent — for the thoughtful reader.","category":"books","thumbnail":"/theme-previews/dawn.svg","settings":{"primaryColor":"#3B4F6B","secondaryColor":"#2C3E50","accentColor":"#C0832B","backgroundColor":"#FFFFFF","textColor":"#2C2C2C","surfaceColor":"#FDF6EC","fontFamily":"Source Sans Pro","bodyFontFamily":"Source Sans Pro","headingFontFamily":"Libre Baskerville","borderRadius":4},"preview":{"label":"Dawn","summary":"Calm and scholarly for bookshops, stationery, and educational content. Warm parchment tones with a slate-blue accent — for the thoughtful reader.","swatches":["#3B4F6B","#C0832B","#FDF6EC"],"headingFont":"Libre Baskerville","sectionCount":7}},{"id":"7b669c70-0000-4000-8000-000000000008","slug":"letbuyy-bloom","name":"Bloom","presetId":"bloom","description":"Warm and playful for pet food, accessories, and veterinary products. Sunny tangerine and leaf green — the colours of a happy pet store.","category":"pet","thumbnail":"/theme-previews/bloom.svg","settings":{"primaryColor":"#E07B39","secondaryColor":"#B55E24","accentColor":"#4CAF73","backgroundColor":"#FFFFFF","textColor":"#2C1A0A","surfaceColor":"#FFF9F0","fontFamily":"Inter","bodyFontFamily":"Inter","headingFontFamily":"Inter","borderRadius":14},"preview":{"label":"Bloom","summary":"Warm and playful for pet food, accessories, and veterinary products. Sunny tangerine and leaf green — the colours of a happy pet store.","swatches":["#E07B39","#4CAF73","#FFF9F0"],"headingFont":"Inter","sectionCount":7}},{"id":"7b669c70-0000-4000-8000-000000000009","slug":"letbuyy-nova","name":"Nova","presetId":"nova","description":"Bold and contemporary for direct-to-consumer brands and general merchandise. Deep violet and amber — brand-forward for any product category.","category":"General","thumbnail":"/theme-previews/nova.svg","settings":{"primaryColor":"#8B5CF6","secondaryColor":"#6D28D9","accentColor":"#F59E0B","backgroundColor":"#FFFFFF","textColor":"#1A1A2E","surfaceColor":"#F8FAFC","fontFamily":"Inter","bodyFontFamily":"Inter","headingFontFamily":"Inter","borderRadius":10},"preview":{"label":"Nova","summary":"Bold and contemporary for direct-to-consumer brands and general merchandise. Deep violet and amber — brand-forward for any product category.","swatches":["#8B5CF6","#F59E0B","#F8FAFC"],"headingFont":"Inter","sectionCount":7}},{"id":"7b669c70-0000-4000-8000-000000000010","slug":"letbuyy-summit","name":"Summit","presetId":"summit","description":"Clean and professional for multi-category stores and general retail. Teal and lime — a versatile, safe baseline for any type of online store.","category":"general","thumbnail":"/theme-previews/summit.svg","settings":{"primaryColor":"#00B3B3","secondaryColor":"#008080","accentColor":"#A4E500","backgroundColor":"#FFFFFF","textColor":"#1A1A2E","surfaceColor":"#F9FAFB","fontFamily":"Inter","bodyFontFamily":"Inter","headingFontFamily":"Inter","borderRadius":12},"preview":{"label":"Summit","summary":"Clean and professional for multi-category stores and general retail. Teal and lime — a versatile, safe baseline for any type of online store.","swatches":["#00B3B3","#A4E500","#F9FAFB"],"headingFont":"Inter","sectionCount":6}}]$listings$::jsonb) LOOP
  IF EXISTS(SELECT 1 FROM public.themes WHERE slug=item->>'slug' AND id<>(item->>'id')::uuid) THEN
   RAISE EXCEPTION 'Catalog slug already belongs to another theme'; END IF;
  doc:=base.default_template||jsonb_build_object('themeId',item->>'slug','experienceId',item->>'presetId','rendererEngine','liquid',
   'themeSettings',coalesce(base.default_template->'themeSettings','{}')||(item->'settings'));
  bundle:=doc->'liquidBundle';
  bundle:=jsonb_set(bundle,'{package,slug}',item->'slug');
  bundle:=jsonb_set(bundle,'{package,name}',item->'name');
  bundle:=jsonb_set(bundle,'{config,settings_data,current}',coalesce(bundle#>'{config,settings_data,current}','{}')||(item->'settings'));
  doc:=jsonb_set(doc,'{liquidBundle}',bundle);
  INSERT INTO public.themes(id,slug,name,site_type,category,description,long_description,thumbnail_url,preview_url,
   is_active,is_premium,price,author,version,sort_order,letbuyy_pricing_type,letbuyy_price_inr,letbuyy_price_usd,
   supported_site_types,supported_platforms,theme_preset_id,config,default_template,settings_schema,section_schemas,block_schemas,
   renderer_manifest,schema_version,renderer_version,features,tags,industry)
  VALUES((item->>'id')::uuid,item->>'slug',item->>'name','store',item->>'category',item->>'description',item->>'description',
   item->>'thumbnail',NULL,true,false,0,'LetBuyy',base.version,100, 'free',0,0,
   base.supported_site_types,base.supported_platforms,item->>'presetId',
   jsonb_build_object('preset_id',item->>'presetId','colors',jsonb_build_object('primary',item#>>'{settings,primaryColor}',
    'accent',item#>>'{settings,accentColor}','background',item#>>'{settings,backgroundColor}','text',item#>>'{settings,textColor}')),
   doc,base.settings_schema,base.section_schemas,base.block_schemas,base.renderer_manifest,
   base.schema_version,base.renderer_version,ARRAY['Responsive layouts','Visual editor','Free'],ARRAY['first-party',item->>'presetId'],ARRAY[item->>'category'])
  ON CONFLICT(slug) DO NOTHING;
 END LOOP;
END $catalog$;
COMMIT;
